const rows = $input.all().map(item => item.json);
const PENDING_STATUSES = new Set(['NotStarted', 'InProgress', 'Waiting', 'Failed', 'Unknown']);
const GUID = '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}';

function parsePreList(raw) {
  if (raw === null || raw === undefined || raw === '') return [];
  let str = String(raw).replace(/\s+/g, '');
  str = str.replace(new RegExp(`:(${GUID})([,}])`, 'g'), ':"$1"$2');
  try {
    const parsed = JSON.parse(str);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return null;
  }
}

const keyOf = (workspaceId, datasetId) => `${workspaceId}::${datasetId}`;
const byKey = new Map();
for (const row of rows) {
  byKey.set(keyOf(row.WORKSPACE_ID, row.DATASET_ID), row);
}

const isSomeonesPrerequisite = new Set();
for (const row of rows) {
  const preList = parsePreList(row.PRE_WORKFLOW_LIST);
  if (!preList) continue;
  for (const pre of preList) {
    isSomeonesPrerequisite.add(keyOf(pre.PRE_WORKSPACE_ID, pre.PRE_DATAFLOW_ID));
  }
}

const roots = rows.filter(row =>
  !isSomeonesPrerequisite.has(keyOf(row.WORKSPACE_ID, row.DATASET_ID)) &&
  PENDING_STATUSES.has(row.STATUS)
);

const printedFull = new Set();
const lines = [];

function renderNode(row, depth, isFirstRoot) {
  const key = keyOf(row.WORKSPACE_ID, row.DATASET_ID);

  let prefix;
  if (depth === 0) {
    prefix = isFirstRoot ? '' : '\n';
  } else {
    prefix = '  '.repeat(depth - 1) + '└─ ';
  }

  const label = `${prefix}[${row.TYPE}] ${row.DATASET_NAME} - ${row.STATUS}`;

  if (printedFull.has(key)) {
    lines.push(`${label}(共用依賴，詳見上方)`);
    return;
  }
  printedFull.add(key);
  lines.push(label);

  const preList = parsePreList(row.PRE_WORKFLOW_LIST);
  if (preList === null) {
    lines.push(`${'  '.repeat(depth)}└─ ⚠ PRE_WORKFLOW_LIST 格式錯誤，無法解析前置依賴`);
    return '';
  }
  for (const pre of preList) {
    const child = byKey.get(keyOf(pre.PRE_WORKSPACE_ID, pre.PRE_DATAFLOW_ID));
    if (!child) {
      lines.push(`${'  '.repeat(depth)}└─ ⚠ 找不到對應任務 (WORKSPACE_ID=${pre.PRE_WORKSPACE_ID}, DATASET_ID=${pre.PRE_DATAFLOW_ID})`);
      continue;
    }
    if (!PENDING_STATUSES.has(child.STATUS)) continue;
    renderNode(child, depth + 1);
  }
}

for (let i = 0; i < roots.length; i++) {
  renderNode(roots[i], 0, i === 0);
}

if (lines.length === 0) {
  lines.push('所有任務皆 Success。');
}

return [{ json: { textMap: lines.join('\n').trim() } }];
